// All BSON types demonstrated in one document
db.examples.insertOne({

  // String
  firstName:     "Shivam",
  email:         "shivam@example.com",

  // Number — Int32
  age:           25,

  // Number — Double (decimal)
  rating:        4.8,

  // Decimal128 — high precision (finance/science)
  price:         NumberDecimal("999.9999"),

  // Boolean
  isActive:      true,
  isDeleted:     false,

  // Date
  createdAt:     new Date(),
  birthDate:     ISODate("2000-01-15T00:00:00Z"),

  // ObjectId — auto-generated _id, or manual reference
  _id:           ObjectId(),
  roleId:        ObjectId("66abc123456def789012abcd"),

  // Array — mixed or uniform
  skills:        ["Node.js", "MongoDB", "TypeScript"],
  scores:        [95, 87, 92],

  // Object — embedded/nested document
  address: {
    city:        "Delhi",
    state:       "Delhi",
    pinCode:     "110001",
    country:     "India"
  },

  // Null — explicit absence of value
  middleName:    null,

  // Binary — raw bytes (images, files, UUIDs)
  profilePicture: BinData(0, "aGVsbG8=")

})

// ── $eq ── exact match (same as shorthand)
db.users.find({ age: { $eq: 25 } })
db.users.find({ age: 25 })              // shorthand — identical result

// ── $ne ── not equal
db.users.find({ role: { $ne: "guest" } })
db.users.find({ status: { $ne: "banned" } })

// ── $gt ── greater than
db.users.find({ age: { $gt: 18 } })     // age > 18
db.products.find({ price: { $gt: 500 } })

// ── $gte ── greater than or equal
db.users.find({ age: { $gte: 18 } })    // age >= 18 (includes 18)
db.orders.find({ total: { $gte: 1000 } })

// ── $lt ── less than
db.users.find({ age: { $lt: 30 } })     // age < 30
db.products.find({ price: { $lt: 999 } })

// ── $lte ── less than or equal
db.users.find({ age: { $lte: 60 } })    // age <= 60
db.products.find({ stock: { $lte: 10 } })

// ── $in ── match any value in array
db.users.find({ role: { $in: ["admin", "manager", "superadmin"] } })
db.products.find({ category: { $in: ["electronics", "mobiles"] } })

// ── $nin ── exclude values in array
db.users.find({ role: { $nin: ["guest", "banned"] } })
db.products.find({ status: { $nin: ["draft", "archived"] } })

// ── Combine comparison operators on one field
db.users.find({ age: { $gte: 18, $lte: 60 } })  // 18 <= age <= 60
db.products.find({ price: { $gt: 100, $lt: 1000 } })

// ── $and ── ALL conditions must be true
// Explicit form
db.users.find({
  $and: [
    { age: { $gte: 18 } },
    { isActive: true },
    { role: "user" }
  ]
})

// Implicit $and — same result, cleaner syntax
db.users.find({
  age: { $gte: 18 },
  isActive: true,
  role: "user"
})

// Use explicit $and when the SAME field has multiple conditions
db.products.find({
  $and: [
    { price: { $gt: 100 } },
    { price: { $lt: 1000 } }
  ]
})
// Shorthand for same field range:
db.products.find({ price: { $gt: 100, $lt: 1000 } })


// ── $or ── at least ONE condition must be true
db.users.find({
  $or: [
    { role: "admin" },
    { role: "manager" }
  ]
})

// Search by name OR email
db.users.find({
  $or: [
    { email: "shivam@example.com" },
    { phone: "9999999999" }
  ]
})

// Combine $and + $or
db.users.find({
  isActive: true,
  $or: [
    { role: "admin" },
    { role: "manager" }
  ]
})


// ── $nor ── NONE of the conditions can be true
db.users.find({
  $nor: [
    { role: "guest" },
    { isActive: false },
    { isDeleted: true }
  ]
})
// Returns docs where role != guest AND isActive != false AND isDeleted != true


// ── $not ── negate a condition on ONE field
db.users.find({ age: { $not: { $lt: 18 } } })
// Returns docs where age is NOT less than 18
// (same as age >= 18, but also matches docs where age field doesn't exist)

db.users.find({ role: { $not: { $in: ["guest", "banned"] } } })
// Returns docs where role is not guest and not banned

// ── $exists ── check if a field exists in document

// Find documents where 'phone' field EXISTS
db.users.find({ phone: { $exists: true } })

// Find documents where 'phone' field is MISSING
db.users.find({ phone: { $exists: false } })

// Find documents where 'deletedAt' has been set (soft-delete check)
db.users.find({ deletedAt: { $exists: true } })

// Find active users — deletedAt not set at all
db.users.find({ deletedAt: { $exists: false } })

// null vs $exists: false
db.users.find({ middleName: null })             // matches null OR missing
db.users.find({ middleName: { $exists: false }}) // matches ONLY missing


// ── $type ── check the BSON type of a field value

// Find docs where 'age' is a number
db.users.find({ age: { $type: "number" } })
db.users.find({ age: { $type: 16 } })           // 16 = Int32

// Find docs where 'age' is stored as string (data quality issue)
db.users.find({ age: { $type: "string" } })

// Find docs where '_id' is ObjectId
db.users.find({ _id: { $type: "objectId" } })

// Find docs where 'tags' is an array
db.users.find({ tags: { $type: "array" } })

// Find docs where a field is null type
db.users.find({ middleName: { $type: "null" } })

// Multiple types — match string OR number
db.users.find({ age: { $type: ["string", "number"] } })

// ── $regex ── pattern matching

// Case-insensitive search
db.users.find({ name: { $regex: /shivam/i } })

// Starts with 'Shiv'
db.users.find({ name: { $regex: /^Shiv/ } })

// Ends with '.com'
db.users.find({ email: { $regex: /\.com$/ } })

// String syntax instead of regex literal
db.users.find({ name: { $regex: "shivam", $options: "i" } })

// Contains 'kumar' anywhere (case-insensitive)
db.users.find({ name: { $regex: "kumar", $options: "i" } })


// ── $text ── full-text search
// Step 1: Create a text index (required first)
db.articles.createIndex({ title: "text", content: "text" })

// Step 2: Use $text to search
db.articles.find({ $text: { $search: "mongodb" } })

// Search multiple words (any word matches)
db.articles.find({ $text: { $search: "mongodb aggregation" } })

// Exact phrase search (wrap in quotes)
db.articles.find({ $text: { $search: "\"aggregation pipeline\"" } })

// Exclude a word with minus
db.articles.find({ $text: { $search: "mongodb -sql" } })

// Sort by relevance score
db.articles.find(
  { $text: { $search: "mongodb" } },
  { score: { $meta: "textScore" } }
).sort({ score: { $meta: "textScore" } })


// ── $expr ── compare two fields in same document
// Find orders where discount > tax
db.orders.find({
  $expr: { $gt: ["$discount", "$tax"] }
})

// Find users where firstName equals lastName (edge case)
db.users.find({
  $expr: { $eq: ["$firstName", "$lastName"] }
})

// Find products where price > originalPrice (price increased)
db.products.find({
  $expr: { $gt: ["$price", "$originalPrice"] }
})

// ── $all ── array must contain ALL specified values
db.users.find({ skills: { $all: ["Node.js", "MongoDB"] } })
// Matches users who have BOTH Node.js AND MongoDB (order doesn't matter)

db.products.find({ tags: { $all: ["sale", "featured"] } })
// Matches products tagged as BOTH sale AND featured


// ── $size ── exact array length
db.users.find({ skills: { $size: 3 } })
// Matches users who have EXACTLY 3 skills

db.orders.find({ items: { $size: 1 } })
// Matches orders with exactly 1 item


// ── $elemMatch ── one element must satisfy all conditions
// Array of objects: scores = [{ subject: "Math", score: 95 }, ...]
db.students.find({
  scores: {
    $elemMatch: {
      subject: "Math",
      score:   { $gte: 90 }
    }
  }
})
// Matches students with a Math score >= 90 (same element must satisfy BOTH)

// Without $elemMatch — WRONG for object arrays
// This would match if 'subject' is Math in one element
// AND 'score' >= 90 in ANY other element
db.students.find({
  "scores.subject": "Math",
  "scores.score":   { $gte: 90 }
})

// Dot notation — query field inside array of objects
db.orders.find({ "items.productId": "abc123" })
db.users.find({ "address.city": "Delhi" })

// ── $set ── set specific fields (most common)
db.users.updateOne(
  { _id: id },
  { $set: { firstName: "Shivam", age: 25 } }
)
// Only firstName and age are changed. Everything else untouched.


// ── $unset ── completely remove a field
db.users.updateOne(
  { _id: id },
  { $unset: { temporaryToken: "", resetCode: "" } }
)
// temporaryToken and resetCode fields are deleted from document


// ── $inc ── increment / decrement
db.users.updateOne(
  { _id: id },
  { $inc: { loginCount: 1 } }   // loginCount + 1
)

db.products.updateOne(
  { _id: productId },
  { $inc: { stock: -1 } }        // stock - 1 (decrement)
)

db.posts.updateOne(
  { _id: postId },
  { $inc: { views: 1, likes: 1 } }  // multiple increments
)


// ── $mul ── multiply a field value
db.products.updateMany(
  { category: "electronics" },
  { $mul: { price: 1.10 } }     // increase price by 10%
)


// ── $rename ── rename a field
db.users.updateMany(
  {},
  { $rename: { "name": "fullName" } }  // rename 'name' to 'fullName'
)


// ── $min ── update only if new value is LESS than current
db.products.updateOne(
  { _id: id },
  { $min: { lowestPrice: 499 } }  // set only if 499 < current lowestPrice
)


// ── $max ── update only if new value is GREATER than current
db.users.updateOne(
  { _id: id },
  { $max: { highScore: 9500 } }   // set only if 9500 > current highScore
)


// ── $currentDate ── set field to current date
db.users.updateOne(
  { _id: id },
  {
    $currentDate: {
      lastLoginAt: true,                      // sets to current Date
      lastLoginTimestamp: { $type: "timestamp" }  // sets to Timestamp
    }
  }
)

// ── $push ── add one element to array
db.users.updateOne(
  { _id: id },
  { $push: { skills: "TypeScript" } }
)

// $push with $each — add multiple elements at once
db.users.updateOne(
  { _id: id },
  { $push: { skills: { $each: ["Docker", "AWS", "Redis"] } } }
)

// $push with $each + $position — insert at index 0 (beginning)
db.users.updateOne(
  { _id: id },
  { $push: { skills: { $each: ["Go"], $position: 0 } } }
)

// $push with $slice — keep only last 5 notifications
db.users.updateOne(
  { _id: id },
  {
    $push: {
      notifications: {
        $each:  [{ msg: "New login", at: new Date() }],
        $slice: -5   // keep last 5 only
      }
    }
  }
)


// ── $pull ── remove matching elements
db.users.updateOne(
  { _id: id },
  { $pull: { skills: "PHP" } }  // remove "PHP" from skills array
)

// $pull with condition — remove elements matching criteria
db.orders.updateOne(
  { _id: orderId },
  { $pull: { items: { price: { $lt: 10 } } } }  // remove cheap items
)


// ── $addToSet ── add only if not already present
db.users.updateOne(
  { _id: id },
  { $addToSet: { tags: "nodejs" } }  // no duplicate if "nodejs" exists
)

// $addToSet with $each
db.users.updateOne(
  { _id: id },
  { $addToSet: { tags: { $each: ["mongodb", "typescript"] } } }
)


// ── $pop ── remove first or last element
db.users.updateOne(
  { _id: id },
  { $pop: { skills: 1 } }   //  1 = remove LAST element
)
db.users.updateOne(
  { _id: id },
  { $pop: { skills: -1 } }  // -1 = remove FIRST element
)


// ── $pullAll ── remove multiple exact values at once
db.users.updateOne(
  { _id: id },
  { $pullAll: { skills: ["PHP", "jQuery", "Flash"] } }
)

// ── Include specific fields ──────────────────
db.users.find({}, { firstName: 1, email: 1 })
// Returns: { _id, firstName, email }

// Exclude _id too
db.users.find({}, { firstName: 1, email: 1, _id: 0 })
// Returns: { firstName, email } only


// ── Exclude specific fields ──────────────────
db.users.find({}, { password: 0, __v: 0 })
// Returns everything EXCEPT password and __v

db.users.find({}, { password: 0, createdAt: 0, updatedAt: 0 })


// ── You CANNOT mix 0 and 1 (except _id) ─────
// WRONG:
db.users.find({}, { name: 1, password: 0 })  // Error!

// CORRECT — only exception is _id:
db.users.find({}, { name: 1, email: 1, _id: 0 })  // valid


// ── $slice ── limit array elements returned ──
// Return first 3 skills
db.users.find({}, { skills: { $slice: 3 } })

// Return last 3 skills
db.users.find({}, { skills: { $slice: -3 } })

// Return skills starting at index 2, next 5 elements
db.users.find({}, { skills: { $slice: [2, 5] } })


// Mongoose .select() — equivalent to projection
await User.find().select("firstName email -_id")
await User.find().select("-password -__v")
await User.findById(id).select("+password")  // include usually-excluded field
